Ltac case_cond := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) => let H := fresh "HC" in destruct c eqn:H end.

Section Rnd.
Hypothesis VFdiv : vf_spec 0x13cd64 112.
Hypothesis VFadd : vf_spec 0x13c444 48.
Hypothesis VFmul : vf_spec 0x13bb14 80.
Hypothesis VFle : vf_spec 0x13b990 0.

(* [comment removed for export] *)
Lemma rndA_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a5 a6 a7 s4 s5 s6 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo B ia iz id i ns pfx : Z) (ws : list word) (jA jB : list byte) (wd c0 c1 c2 c3 : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 112 <= bv_unsigned sp)%Z -> (bv_unsigned sp <= B)%Z ->
  u32arr rsegs m B ws -> (0 <= ia <= id)%Z -> (id < iz <= Z.of_nat (length ws))%Z -> (Z.of_nat (length ws) <= 128)%Z ->
  (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z ->
  nth_error ws (Z.to_nat id) = Some wd -> (bv_unsigned wd < 1000000000)%Z ->
  (i = 10 \/ i = 100 \/ i = 1000 \/ i = 10000 \/ i = 100000 \/ i = 1000000 \/ i = 10000000 \/ i = 100000000 \/ i = 1000000000)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -544) [C8 c0; CB 32 jA; C8 (Z_to_bv 64 (B + 4 * id)); C8 c1; C8 c2; C8 c3; CB 16 jB; C8 (Z_to_bv 64 ns); C8 (Z_to_bv 64 pfx)] ->
  let v := bv_unsigned wd in let x := (v mod i)%Z in
  evt rsegs (fun ms' => exists ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s9' t3' t4' t5' t6' fc' m' jA1 rlo,
      ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (B + 4 * ia))
                    a0' a1' a2' a3' a4' a5' a6' a7'
                    (Z_to_bv 64 (B + 4 * id + 65536)) (Z_to_bv 64 i) s4 s5 s6 (Z_to_bv 64 x) wd s9'
                    (Z_to_bv 64 (B + 4 * (id + 1))) (Z_to_bv 64 (B + 4 * iz)) t3' t4' t5' t6') F
               (Z_to_bv 64 0x142288) fc' None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 112, bv_unsigned sp); (bv_unsigned s0 + -536, bv_unsigned s0 + -504)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws /\ length jA1 = 16%nat
      /\ rw_cells rsegs m' (bv_unsigned s0 + -544) [C8 c0; CB 16 jA1; C8 (Z_to_bv 64 (B + 4 * id + 65532)); C8 rlo; C8 (Z_to_bv 64 (B + 4 * id)); C8 c1; C8 c2; C8 c3; CB 16 jB; C8 (Z_to_bv 64 ns); C8 (Z_to_bv 64 pfx)])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia))
                    a0 a1 a2 a3 (Z_to_bv 64 (B + 4 * id + 65532)) a5 a6 a7
                    (Z_to_bv 64 (B + 4 * id + 65536)) (Z_to_bv 64 i) s4 s5 s6 (Z_to_bv 64 x) wd (Z_to_bv 64 (v / i))
                    (Z_to_bv 64 (B + 4 * (id + 1))) (Z_to_bv 64 (B + 4 * iz)) t3 t4 t5 t6) F
               (Z_to_bv 64 0x142210) fc None m (seg_rom rsegs)).
Proof.
