(* [comment removed for export] *)
Fixpoint upds (ws : list word) (i : nat) (l : list Z) : list word :=
  match l with [] => ws | v :: l' => upds (upd ws i (Z_to_bv 64 v)) (S i) l' end.
Lemma upds_length ws i l : length (upds ws i l) = length ws.
Proof.
